      { title: 'After restore', completed: 0, priority: 'Low', project_id: 1 }
    ]);
    saved.close();
    assert.match(await get('/'), /1\/4 completed/);
  } finally {
    if (server) await server.stop();
    await rm(dir, { recursive: true, force: true });
  }
});

